export interface FinancialTransactionRecord {
  id: string;
  invoiceCode: string;
  date: string;
  type: "tuition_income" | "instructor_payout" | "platform_license" | "center_expense";
  typeLabelAr: string;
  typeLabelEn: string;
  partyNameAr: string;
  partyNameEn: string;
  courseOrItemAr: string;
  courseOrItemEn: string;
  grossAmountEgp: number;
  centerShareEgp: number;
  instructorShareEgp: number;
  paymentMethodAr: string;
  paymentMethodEn: string;
  status: "completed" | "pending_settlement" | "verified";
}

export interface StudentCrmRecord {
  id: string;
  studentCode: string;
  fullNameAr: string;
  fullNameEn: string;
  trackAr: string;
  trackEn: string;
  branchAr: string;
  branchEn: string;
  attendanceRate: number;
  examAverage: number;
  completedAssignments: number;
  totalAssignments: number;
  parentPhone: string;
  subscriptionStatus: "paid" | "installment" | "renewal_due";
  lastCheckIn: string;
}

export interface SecurityAuditEndpointItem {
  id: string;
  method: "GET" | "POST" | "PUT" | "DELETE" | "RULES";
  endpoint: string;
  moduleAr: string;
  moduleEn: string;
  authLevel: "Public" | "Authenticated Client" | "Admin RBAC" | "System Webhook";
  encryption: string;
  rateLimit: string;
  status: "hardened" | "verified";
}

